INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('fcd86861-4f75-4dd4-8729-f497ef67c45b', '70f3e292-d3b2-52d4-afc6-92717648ad63', 'en', 'FrameDEV 22', 'A single-storey house with a flat roof, with 93.7 m² of usable area. 3 bedrooms and 3 bathrooms. An open carport integrated into the building (it can be enclosed as a full garage) and a living room with a fireplace. Mechanical ventilation with heat recovery.', '2026-10-22T13:30:47.071Z'::timestamptz, '2026-10-22T13:30:47.071Z'::timestamptz, '[{"id":"fdpl-zx117-room-0","name":"Entrance hall"},{"id":"fdpl-zx117-room-1","name":"Living room"},{"id":"fdpl-zx117-room-2","name":"Kitchen"},{"id":"fdpl-zx117-room-3","name":"Toilet"},{"id":"fdpl-zx117-room-4","name":"Hall"},{"id":"fdpl-zx117-room-5","name":"Room"},{"id":"fdpl-zx117-room-6","name":"Room"},{"id":"fdpl-zx117-room-7","name":"Room"},{"id":"fdpl-zx117-room-8","name":"Bathroom"},{"id":"fdpl-zx117-room-9","name":"Bathroom"},{"id":"fdpl-zx117-room-10","name":"Utility room"}]'::jsonb, '[{"id":"fdpl-zx117-faq-1","answer":"Yes, the estimated price of the All-Inclusive package is PLN 649,110. It covers everything in the Turnkey package plus the foundation slab, heat recovery ventilation, a made-to-measure kitchen with full appliances and complete bathroom fittings (taps, sanitaryware, tiles). Full furnishing is an option priced individually.","question":"Is the All-Inclusive package available and how much does it cost?"},{"id":"fdpl-zx117-faq-2","answer":"The investment is split into eight stages and the next instalment is paid after the previous result has been checked: 10% design and reservation, 20% machine start-up, 10% factory acceptance, 10% packing and shipping, 10% materials on site, 10% shell assembly, 15% shell-and-core stage, 15% handover of keys. After the contract is signed the price of materials is frozen for the whole construction period.","question":"What is the payment schedule and is the price fixed?"},{"id":"fdpl-zx117-faq-3","answer":"From order to handover of the keys the build takes 4-6 months, with on-site assembly of up to 14 days. The producer provides transport and assembly; the foundation slab is an extra cost outside the All-Inclusive package, and soil replacement is charged at actual cost.","question":"How long does the build take from order to handover of the keys?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Prefabricated LGS steel frame (galvanised profiles) with mineral wool filling, cement-bonded particleboard, wind barrier and 150 mm facade insulation.', 'Flat roof, covering: PVC membrane or bitumen felt', 'The design can be adapted with the producer''s architects: changing the partition layout, the size and placement of windows and modifying the building form.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('bfc1812d-9d30-4908-ac73-949570608b00', '70f3e292-d3b2-52d4-afc6-92717648ad63', 'de', 'FrameDEV 22', 'Ein eingeschossiges Haus mit Flachdach, mit 93,7 m² Nutzfläche. 3 Schlafzimmer und 3 Badezimmer. Ein in den Baukörper integrierter offener Carport (kann zur Vollgarage geschlossen werden) und ein Wohnzimmer mit Kamin. Mechanische Lüftung mit Wärmerückgewinnung.', '2026-10-22T13:30:47.071Z'::timestamptz, '2026-10-22T13:30:47.071Z'::timestamptz, '[{"id":"fdpl-zx117-room-0","name":"Eingangshalle"},{"id":"fdpl-zx117-room-1","name":"Wohnzimmer"},{"id":"fdpl-zx117-room-2","name":"Küche"},{"id":"fdpl-zx117-room-3","name":"WC"},{"id":"fdpl-zx117-room-4","name":"Diele"},{"id":"fdpl-zx117-room-5","name":"Zimmer"},{"id":"fdpl-zx117-room-6","name":"Zimmer"},{"id":"fdpl-zx117-room-7","name":"Zimmer"},{"id":"fdpl-zx117-room-8","name":"Badezimmer"},{"id":"fdpl-zx117-room-9","name":"Badezimmer"},{"id":"fdpl-zx117-room-10","name":"Hauswirtschaftsraum"}]'::jsonb, '[{"id":"fdpl-zx117-faq-1","answer":"Ja, der geschätzte Preis des Pakets All-Inclusive beträgt 649.110 PLN. Es umfasst alles aus dem Paket Schlüsselfertig plus Fundamentplatte, Lüftung mit Wärmerückgewinnung, eine Maßküche mit kompletten Geräten und die vollständige Badausstattung (Armaturen, Sanitärkeramik, Fliesen). Die vollständige Möblierung ist eine individuell kalkulierte Option.","question":"Gibt es das Paket All-Inclusive und was kostet es?"},{"id":"fdpl-zx117-faq-2","answer":"Die Investition ist in acht Etappen aufgeteilt, die nächste Rate wird nach Prüfung des vorherigen Ergebnisses gezahlt: 10 % Entwurf und Reservierung, 20 % Anlauf der Maschinen, 10 % Werksabnahme, 10 % Verpackung und Versand, 10 % Material auf dem Grundstück, 10 % Montage des Rohbaus, 15 % Bauträgerstandard, 15 % Schlüsselübergabe. Nach Vertragsabschluss wird der Materialpreis für die gesamte Bauzeit eingefroren.","question":"Wie sieht der Zahlungsplan aus und ist der Preis fest?"},{"id":"fdpl-zx117-faq-3","answer":"Von der Bestellung bis zur Schlüsselübergabe dauert die Realisierung 4-6 Monate, die Montage auf dem Grundstück bis zu 14 Tage. Der Hersteller übernimmt Transport und Montage; die Fundamentplatte ist außerhalb des Pakets All-Inclusive ein Zusatzposten, der Bodenaustausch wird nach tatsächlichen Kosten abgerechnet.","question":"Wie lange dauert die Realisierung von der Bestellung bis zur Schlüsselübergabe?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vorgefertigtes LGS-Stahlskelett (verzinkte Profile) mit Mineralwolle-Füllung, zementgebundener Spanplatte, Winddichtung und 150 mm Fassadendämmung.', 'Flachdach, Eindeckung: PVC-Folie oder Bitumenbahn', 'Der Entwurf kann mit den Architekten des Herstellers angepasst werden: Änderung der Trennwände, Größe und Anordnung der Fenster sowie Änderung der Gebäudeform.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('248b1475-7103-4bce-a32a-21f91538e091', '70f3e292-d3b2-52d4-afc6-92717648ad63', 'nl', 'FrameDEV 22', 'Een gelijkvloerse woning met plat dak, met 93,7 m² bruikbare oppervlakte. 3 slaapkamers en 3 badkamers. Een in het gebouw geïntegreerde open carport (te sluiten tot een volledige garage) en een woonkamer met open haard. Mechanische ventilatie met warmteterugwinning.', '2026-10-22T13:30:47.071Z'::timestamptz, '2026-10-22T13:30:47.071Z'::timestamptz, '[{"id":"fdpl-zx117-room-0","name":"Entree"},{"id":"fdpl-zx117-room-1","name":"Woonkamer"},{"id":"fdpl-zx117-room-2","name":"Keuken"},{"id":"fdpl-zx117-room-3","name":"Toilet"},{"id":"fdpl-zx117-room-4","name":"Hal"},{"id":"fdpl-zx117-room-5","name":"Kamer"},{"id":"fdpl-zx117-room-6","name":"Kamer"},{"id":"fdpl-zx117-room-7","name":"Kamer"},{"id":"fdpl-zx117-room-8","name":"Badkamer"},{"id":"fdpl-zx117-room-9","name":"Badkamer"},{"id":"fdpl-zx117-room-10","name":"Bijkeuken"}]'::jsonb, '[{"id":"fdpl-zx117-faq-1","answer":"Ja, de geschatte prijs van het pakket All-Inclusive is 649.110 PLN. Het omvat alles uit het pakket Sleutelklaar plus de funderingsplaat, ventilatie met warmteterugwinning, een keuken op maat met complete apparatuur en volledige badkamerinrichting (kranen, sanitair, tegels). Volledige meubilering is een optie die individueel wordt geprijsd.","question":"Is het pakket All-Inclusive beschikbaar en wat kost het?"},{"id":"fdpl-zx117-faq-2","answer":"De investering is verdeeld over acht etappes en de volgende termijn wordt betaald nadat het vorige resultaat is gecontroleerd: 10% ontwerp en reservering, 20% opstarten van de machines, 10% fabrieksoplevering, 10% verpakking en verzending, 10% materiaal op de bouwplaats, 10% montage van de ruwbouw, 15% casco-stadium, 15% overdracht van de sleutels. Na ondertekening van het contract wordt de materiaalprijs voor de hele bouwperiode bevroren.","question":"Hoe ziet het betalingsschema eruit en is de prijs vast?"},{"id":"fdpl-zx117-faq-3","answer":"Van bestelling tot overdracht van de sleutels duurt de realisatie 4-6 maanden, met een montage op de bouwplaats van maximaal 14 dagen. De producent verzorgt transport en montage; de funderingsplaat is buiten het pakket All-Inclusive een meerprijs en grondvervanging wordt tegen werkelijke kosten gerekend.","question":"Hoe lang duurt de realisatie van bestelling tot overdracht van de sleutels?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Geprefabriceerd LGS-staalskelet (verzinkte profielen) met minerale wolvulling, cementgebonden spaanplaat, windscherm en 150 mm gevelisolatie.', 'Plat dak, dekking: PVC-folie of bitumen dakbedekking', 'Het ontwerp kan samen met de architecten van de producent worden aangepast: een andere indeling van de tussenwanden, andere maat en plaatsing van de ramen en een gewijzigde vorm van het gebouw.', NULL) ON CONFLICT DO NOTHING;
